//! Zstandard frame and block decoder (RFC 8878 Section 3).

use std::io;

use super::bits::{ForwardByteReader, ReverseBitReader};
use super::fse::{FseTable, SeqEntry, SeqKind, SeqTable};

/// Entries per table in the gathered sequence-table buffer (max accuracy log 9).
const SEQ_TAB_STRIDE: usize = 512;
use super::huf::HufTable;

const ZSTD_MAGIC: u32 = 0xFD2FB528;
const MIN_WINDOW_LOG: u32 = 10;
const MAX_WINDOW_SIZE: u64 = 1 << 27; // 128 MB cap for safety
/// Maximum decoded size of one zstd block. Used to size the frame-lifetime
/// literals scratch and to reserve output headroom for the SIMD wildcopy.
const ZSTD_BLOCKSIZE_MAX: usize = 128 * 1024;

// ---------------------------------------------------------------------------
// Frame header
// ---------------------------------------------------------------------------

struct FrameHeader {
    window_size: u64,
    content_size: Option<u64>,
    dict_id: Option<u32>,
    content_checksum: bool,
}

fn parse_frame_header(r: &mut ForwardByteReader) -> io::Result<FrameHeader> {
    let magic = r.read_u32_le()?;
    if magic != ZSTD_MAGIC {
        // Check for skippable frame (0x184D2A5X).
        if (magic & 0xFFFFFFF0) == 0x184D2A50 {
            let size = r.read_u32_le()? as usize;
            r.skip(size)?;
            return Err(io::Error::new(io::ErrorKind::Other, "zstd: skippable frame"));
        }
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("zstd: invalid magic number {:08x}", magic),
        ));
    }

    let descriptor = r.read_u8()?;
    let dict_id_flag = descriptor & 3;
    let content_checksum = (descriptor >> 2) & 1 != 0;
    let _reserved = (descriptor >> 3) & 1;
    let _unused = (descriptor >> 4) & 1;
    let single_segment = (descriptor >> 5) & 1 != 0;
    let fcs_field_size_flag = (descriptor >> 6) & 3;

    // Window descriptor (absent if single_segment).
    let window_size = if !single_segment {
        let wd = r.read_u8()?;
        let exponent = (wd >> 3) as u32;
        let mantissa = (wd & 7) as u64;
        let base = 1u64 << (MIN_WINDOW_LOG + exponent);
        base + (base >> 3) * mantissa
    } else {
        0 // Will be set from content_size.
    };

    // Dictionary ID.
    let dict_id = match dict_id_flag {
        0 => None,
        1 => Some(r.read_u8()? as u32),
        2 => Some(r.read_u16_le()? as u32),
        3 => Some(r.read_u32_le()?),
        _ => unreachable!(),
    };

    // Frame Content Size.
    let fcs_field_size = match fcs_field_size_flag {
        0 => {
            if single_segment { 1 } else { 0 }
        }
        1 => 2,
        2 => 4,
        3 => 8,
        _ => unreachable!(),
    };
    let content_size = match fcs_field_size {
        0 => None,
        1 => Some(r.read_u8()? as u64),
        2 => Some(r.read_u16_le()? as u64 + 256),
        4 => Some(r.read_u32_le()? as u64),
        8 => Some(r.read_u64_le()?),
        _ => unreachable!(),
    };

    let window_size = if single_segment {
        content_size.unwrap_or(0)
    } else {
        window_size
    };

    Ok(FrameHeader {
        window_size: window_size.min(MAX_WINDOW_SIZE),
        content_size,
        dict_id,
        content_checksum,
    })
}

// ---------------------------------------------------------------------------
// Block decoding
// ---------------------------------------------------------------------------

/// Decode an entire zstd frame, appending decompressed data to `output`.
/// Returns the number of input bytes consumed.
#[cfg_attr(not(test), allow(dead_code))]
pub fn decode_frame(data: &[u8], output: &mut Vec<u8>) -> io::Result<usize> {
    decode_frame_streaming(data, output, None).map(|(consumed, _)| consumed)
}

/// Largest window for which the streaming mode compacts the buffer; above
/// this the whole frame is buffered (the copy per flush would dominate).
const STREAM_MAX_WINDOW: usize = 8 << 20;

/// Decode one frame. Without a `sink`, everything is appended to `buf`.
/// With a `sink`, `buf` is a scratch buffer: whenever it holds more than
/// `window + chunk` bytes the prefix is written to the sink and the last
/// `window` bytes are moved to the front, so the working set stays around
/// three windows (L2/L3-resident for typical windows) instead of the whole
/// output — like C zstd's streaming ring buffer. Returns
/// `(input bytes consumed, output bytes produced)`; in streaming mode the
/// tail of the frame is left in `buf` for the caller to flush.
pub fn decode_frame_streaming(
    data: &[u8],
    buf: &mut Vec<u8>,
    mut sink: Option<&mut dyn std::io::Write>,
) -> io::Result<(usize, usize)> {
    let output = buf;
    let mut r = ForwardByteReader::new(data);
    let header = match parse_frame_header(&mut r) {
        Err(e) if e.kind() == io::ErrorKind::Other => {
            // Skippable frame — return bytes consumed.
            return Ok((r.position(), 0));
        }
        result => result?,
    };

    if header.dict_id.is_some() {
        return Err(io::Error::new(
            io::ErrorKind::Unsupported,
            "zstd: dictionary decoding not supported",
        ));
    }

    // Streaming: flush when the buffer exceeds `keep + chunk`, keeping the
    // last `keep` (= window) bytes. `chunk = 2 * keep` bounds the compaction
    // copy at a third of the bytes flushed.
    let keep = header.window_size as usize;
    let streaming = sink.is_some() && keep <= STREAM_MAX_WINDOW;
    let chunk = (2 * keep).max(1 << 20);
    if streaming {
        output.clear();
        output.reserve(keep + chunk + ZSTD_BLOCKSIZE_MAX + 32);
    } else if let Some(cs) = header.content_size {
        output.reserve(cs as usize);
    }
    let mut hasher = if header.content_checksum && streaming { Some(Xxh64::new()) } else { None };
    let mut flushed_total: usize = 0;

    let out_start = output.len();

    // Persistent Huffman table (reused across blocks with Treeless mode).
    let mut huf_table: Option<HufTable> = None;
    // Persistent FSE tables (reused with Repeat mode).
    let mut ll_table: Option<SeqTable> = None;
    let mut of_table: Option<SeqTable> = None;
    let mut ml_table: Option<SeqTable> = None;
    // Repeat offsets.
    let mut rep_offsets = [1u32, 4, 8];
    // Frame-lifetime literals scratch. Sized to hold any one block's
    // decompressed literals plus a 32-byte trailing dead zone used by the
    // SIMD wildcopy in the sequence loop. Reused across all blocks in the
    // frame so we allocate once per decode instead of twice per block.
    let mut literals_buf: Vec<u8> = Vec::with_capacity(ZSTD_BLOCKSIZE_MAX + 32);
    // Frame-lifetime gathered sequence tables (see `decode_compressed_block`).
    let mut seq_tabs: Vec<SeqEntry> = Vec::with_capacity(SEQ_TAB_STRIDE * 3);

    loop {
        let block_header = r.read_u24_le()?;
        let last_block = (block_header & 1) != 0;
        let block_type = (block_header >> 1) & 3;
        let block_size = (block_header >> 3) as usize;

        match block_type {
            0 => {
                // Raw block.
                let raw = r.read_bytes(block_size)?;
                output.extend_from_slice(raw);
            }
            1 => {
                // RLE block.
                let byte = r.read_u8()?;
                output.resize(output.len() + block_size, byte);
            }
            2 => {
                // Compressed block.
                let block_data = r.read_bytes(block_size)?;
                decode_compressed_block(
                    block_data,
                    output,
                    &mut huf_table,
                    &mut ll_table,
                    &mut of_table,
                    &mut ml_table,
                    &mut rep_offsets,
                    header.window_size,
                    &mut literals_buf,
                    &mut seq_tabs,
                )?;
            }
            3 => {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "zstd: reserved block type",
                ));
            }
            _ => unreachable!(),
        }

        if last_block {
            break;
        }

        if streaming && output.len() > keep + chunk {
            let flush_len = output.len() - keep;
            if let Some(h) = hasher.as_mut() {
                h.update(&output[..flush_len]);
            }
            sink.as_mut().unwrap().write_all(&output[..flush_len])?;
            flushed_total += flush_len;
            output.copy_within(flush_len.., 0);
            output.truncate(keep);
        }
    }

    // Content checksum (xxhash64, lower 32 bits).
    if header.content_checksum {
        let expected = r.read_u32_le()?;
        let actual = match hasher.as_mut() {
            Some(h) => {
                h.update(&output[..]);
                h.finish() as u32
            }
            None => xxhash64(&output[out_start..], 0) as u32,
        };
        if actual != expected {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!("zstd: content checksum mismatch (expected {:08x}, got {:08x})", expected, actual),
            ));
        }
    }

    let produced = if streaming { flushed_total + output.len() } else { output.len() - out_start };
    // Verify content size if declared.
    if let Some(cs) = header.content_size {
        if produced as u64 != cs {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!("zstd: content size mismatch (header={}, produced={})", cs, produced),
            ));
        }
    }

    Ok((r.position(), produced))
}

// ---------------------------------------------------------------------------
// Compressed block
// ---------------------------------------------------------------------------

#[inline(never)]
fn decode_compressed_block(
    data: &[u8],
    output: &mut Vec<u8>,
    huf_table: &mut Option<HufTable>,
    ll_table: &mut Option<SeqTable>,
    of_table: &mut Option<SeqTable>,
    ml_table: &mut Option<SeqTable>,
    rep_offsets: &mut [u32; 3],
    _window_size: u64,
    literals_buf: &mut Vec<u8>,
    seq_tabs: &mut Vec<SeqEntry>,
) -> io::Result<()> {
    let mut r = ForwardByteReader::new(data);

    // --- Literals Section ---
    // Decode directly into the frame-lifetime scratch (reused across blocks)
    // so we avoid one Vec alloc per block. `decode_literals_section_into`
    // sets the length to the real literal count.
    let (lit_ptr, lit_total) = decode_literals_section_into(&mut r, data, huf_table, literals_buf)?;
    // SAFETY: `lit_ptr` points at `lit_total` literal bytes followed by at
    // least 16 readable bytes (see `decode_literals_section_into`).
    let literals: &[u8] = unsafe { core::slice::from_raw_parts(lit_ptr, lit_total) };

    // Reserve the worst-case output for this block upfront so neither the
    // literal copies nor the per-sequence match wildcopy need to re-check
    // capacity. The `+ 32` is dead-zone padding for the SIMD wildcopy
    // overshoot in `cpu_features::copy_match_unchecked`.
    output.reserve(ZSTD_BLOCKSIZE_MAX + 32);

    // --- Sequences Section ---
    let seq_data = &data[r.position()..];
    if seq_data.is_empty() {
        // No sequences — all data is literals.
        output.extend_from_slice(&literals[..lit_total]);
        return Ok(());
    }

    let mut sr = ForwardByteReader::new(seq_data);
    let num_sequences = decode_sequence_count(&mut sr)?;

    if num_sequences == 0 {
        output.extend_from_slice(&literals[..lit_total]);
        return Ok(());
    }

    // Decode sequence section header (FSE table modes).
    let mode_byte = sr.read_u8()?;
    let ll_mode = (mode_byte >> 6) & 3;
    let of_mode = (mode_byte >> 4) & 3;
    let ml_mode = (mode_byte >> 2) & 3;

    decode_seq_table_mode(&mut sr, ll_mode, ll_table, 35, 9, SeqKind::LitLen)?;
    decode_seq_table_mode(&mut sr, of_mode, of_table, 31, 8, SeqKind::Offset)?;
    decode_seq_table_mode(&mut sr, ml_mode, ml_table, 52, 9, SeqKind::MatchLen)?;

    let ll_t = ll_table.as_ref().unwrap();
    let of_t = of_table.as_ref().unwrap();
    let ml_t = ml_table.as_ref().unwrap();

    let bitstream = &seq_data[sr.position()..];
    // Gather the three tables into one buffer (LL at 0, OF at 512, ML at
    // 1024 — each is at most 1 << 9 entries) so the hot loop indexes off a
    // single base pointer. ~12 KB memcpy per block; negligible.
    seq_tabs.clear();
    seq_tabs.resize(SEQ_TAB_STRIDE * 3, SeqEntry::default());
    seq_tabs[..ll_t.table.len()].copy_from_slice(&ll_t.table);
    seq_tabs[SEQ_TAB_STRIDE..SEQ_TAB_STRIDE + of_t.table.len()].copy_from_slice(&of_t.table);
    seq_tabs[2 * SEQ_TAB_STRIDE..2 * SEQ_TAB_STRIDE + ml_t.table.len()].copy_from_slice(&ml_t.table);
    // SAFETY: literals has 32 bytes of trailing padding beyond `lit_total`;
    // output has `ZSTD_BLOCKSIZE_MAX + 32` bytes of headroom (reserved above).
    let (dst_off, lit_pos) = unsafe {
        decode_sequences(
            bitstream, seq_tabs.as_ptr(),
            [ll_t.accuracy_log, of_t.accuracy_log, ml_t.accuracy_log],
            num_sequences,
            literals.as_ptr(), lit_total,
            output.as_mut_ptr(), output.len(),
            rep_offsets,
        )?
    };
    unsafe { output.set_len(dst_off); }

    // Append remaining literals after all sequences.
    if lit_pos < lit_total {
        output.extend_from_slice(&literals[lit_pos..lit_total]);
    }
    Ok(())
}

/// Loop-carried FSE decoding state for the sequence section.
struct FseState<'a> {
    bits: ReverseBitReader<'a>,
    ll_state: u32,
    of_state: u32,
    ml_state: u32,
    rep: [u32; 3],
    /// Sequences still to decode (including those in the current batch).
    left: usize,
}

/// One decoded sequence. `repr(C)` — the asm batch decoder writes it.
#[derive(Clone, Copy, Default)]
#[repr(C)]
struct Seq {
    lit_len: u32,
    match_len: u32,
    offset: u32,
}
type SeqBatch = [Seq; SEQ_BATCH];
const SEQ_BATCH: usize = 64;

/// Decode ONE sequence with the general-purpose reader: handles the
/// stream-start slow refill, the rare > 31-bit extras mid-refill and the
/// final sequence (no state advance). Mirrors `ZSTD_decodeSequence`:
/// extra bits read Offset→ML→LL, repeat-offset resolution via the `ll0`
/// trick, one refill after the state advance.
///
/// # Safety
/// `tabs` must point at `3 * SEQ_TAB_STRIDE` entries holding the LL, OF,
/// ML tables at strides 0, 1, 2; the states must be valid for them.
#[inline(never)]
unsafe fn decode_sequence_general(st: &mut FseState, tabs: *const SeqEntry) -> Seq {
    let ll_e = unsafe { *tabs.add(st.ll_state as usize) };
    let of_e = unsafe { *tabs.add(SEQ_TAB_STRIDE + st.of_state as usize) };
    let ml_e = unsafe { *tabs.add(2 * SEQ_TAB_STRIDE + st.ml_state as usize) };
    let of_bits = of_e.nb_additional as u32;
    let ml_bits = ml_e.nb_additional as u32;
    let ll_bits = ll_e.nb_additional as u32;
    let bits = &mut st.bits;
    let rep = &mut st.rep;

    let offset = if of_bits > 1 {
        let off = of_e.base_value + bits.get_bits(of_bits);
        rep[2] = rep[1];
        rep[1] = rep[0];
        rep[0] = off;
        off
    } else {
        let ll0 = (ll_e.base_value == 0) as usize;
        if of_bits == 0 {
            let off = rep[ll0];
            rep[1] = rep[1 - ll0];
            rep[0] = off;
            off
        } else {
            let idx = ll0 + 1 + bits.get_bits(1) as usize; // 1..=3
            let temp = if idx == 3 { rep[0].wrapping_sub(1) } else { rep[idx] };
            if idx != 1 {
                rep[2] = rep[1];
            }
            rep[1] = rep[0];
            rep[0] = temp;
            temp
        }
    };
    let match_len = ml_e.base_value + bits.get_bits(ml_bits);
    let lit_len = ll_e.base_value + bits.get_bits(ll_bits);

    st.left -= 1;
    if st.left != 0 {
        st.ll_state = ll_e.next_state as u32 + bits.get_bits(ll_e.nb_bits as u32);
        st.ml_state = ml_e.next_state as u32 + bits.get_bits(ml_e.nb_bits as u32);
        st.of_state = of_e.next_state as u32 + bits.get_bits(of_e.nb_bits as u32);
        bits.refill();
    }
    Seq { lit_len, match_len, offset }
}

/// Fast path: decode up to `n` sequences with no slow paths whatsoever.
///
/// Stops early (returning how many it decoded) when the next sequence
/// needs anything unusual: fewer than 8 source bytes ahead (refill would
/// need the slow path), more than 31 extra bits, or it is the final
/// sequence (no state advance). The caller handles that one sequence with
/// [`decode_sequence_general`] and re-enters.
///
/// The bit state is kept pre-shifted (`container << consumed`) so a read is
/// two dependent shifts, and every value is a plain local so LLVM keeps it
/// in a register (with `&mut` state and inlined slow paths it spilled the
/// FSE states every iteration).
///
/// # Safety
/// As for [`decode_sequence_general`].
#[inline(never)]
#[allow(unused_assignments)]
unsafe fn decode_sequence_batch_rust(st: &mut FseState, tabs: *const SeqEntry, out: &mut SeqBatch, n: usize) -> usize {
    let (mut index, consumed0, container0, src) = st.bits.raw_parts();
    let mut consumed = consumed0;
    let mut acc = container0 << consumed;
    let mut ll_state = st.ll_state;
    let mut of_state = st.of_state;
    let mut ml_state = st.ml_state;
    let [mut r0, mut r1, mut r2] = st.rep;
    let ll_tab = tabs;
    let of_tab = unsafe { tabs.add(SEQ_TAB_STRIDE) };
    let ml_tab = unsafe { tabs.add(2 * SEQ_TAB_STRIDE) };
    // Not the last sequence, and enough bytes ahead for a fast refill.
    let limit = n.min(st.left - 1);
    let mut done = 0usize;

    macro_rules! read {
        ($n:expr) => {{
            let nb: u32 = $n;
            let v = ((acc >> 1) >> (63 ^ nb)) as u32;
            acc <<= nb;
            consumed += nb;
            v
        }};
    }

    while done < limit && index >= 8 {
        // SAFETY: states are < table size by FSE construction.
        let ll_p = unsafe { ll_tab.add(ll_state as usize) };
        let ml_p = unsafe { ml_tab.add(ml_state as usize) };
        let of_p = unsafe { of_tab.add(of_state as usize) };
        let of_bits = unsafe { (*of_p).nb_additional as u32 };
        let ml_bits = unsafe { (*ml_p).nb_additional as u32 };
        let ll_bits = unsafe { (*ll_p).nb_additional as u32 };
        if of_bits + ml_bits + ll_bits > 31 {
            break;
        }

        let offset = if of_bits > 1 {
            let off = unsafe { (*of_p).base_value } + read!(of_bits);
            r2 = r1;
            r1 = r0;
            r0 = off;
            off
        } else {
            let ll0 = unsafe { (*ll_p).base_value } == 0;
            if of_bits == 0 {
                if ll0 {
                    let t = r1;
                    r1 = r0;
                    r0 = t;
                    t
                } else {
                    r0
                }
            } else {
                let idx = ll0 as u32 + 1 + read!(1); // 1..=3
                let temp = if idx == 1 { r1 } else if idx == 2 { r2 } else { r0.wrapping_sub(1) };
                if idx != 1 {
                    r2 = r1;
                }
                r1 = r0;
                r0 = temp;
                temp
            }
        };
        let match_len = unsafe { (*ml_p).base_value } + read!(ml_bits);
        let lit_len = unsafe { (*ll_p).base_value } + read!(ll_bits);
        unsafe { *out.get_unchecked_mut(done) = Seq { lit_len, match_len, offset } };
        done += 1;

        // Advance states (LL, ML, OF: <= 26 bits). Low 4 bytes of an entry =
        // next_state (u16) | nb_bits << 24; volatile so the loads happen
        // here rather than being hoisted across the branches above.
        let ll_w = unsafe { core::ptr::read_volatile(ll_p as *const u32) };
        let ml_w = unsafe { core::ptr::read_volatile(ml_p as *const u32) };
        let of_w = unsafe { core::ptr::read_volatile(of_p as *const u32) };
        ll_state = (ll_w & 0xFFFF) + read!(ll_w >> 24);
        ml_state = (ml_w & 0xFFFF) + read!(ml_w >> 24);
        of_state = (of_w & 0xFFFF) + read!(of_w >> 24);

        // Refill: consumed <= 7 + 31 + 26 = 64 here; index >= 8 guarantees
        // the window stays inside the source.
        index -= (consumed >> 3) as usize;
        consumed &= 7;
        // SAFETY: index + 8 <= source length (index only decreases from a
        // valid window and index >= 8 was checked at loop entry... see
        // `raw_parts`).
        acc = unsafe { u64::from_le(core::ptr::read_unaligned(src.add(index) as *const u64)) } << consumed;
    }

    st.bits.set_raw_parts(index, consumed, acc >> consumed);
    st.ll_state = ll_state;
    st.of_state = of_state;
    st.ml_state = ml_state;
    st.rep = [r0, r1, r2];
    st.left -= done;
    done
}

/// x86_64 + BMI2 version of the fast batch loop (same contract as the
/// portable [`decode_sequence_batch_rust`]). Hand-scheduled because LLVM
/// kept ~15 register-to-register shuffles and a spilled bit container in
/// the portable loop; this is ~70 instructions per sequence with every
/// loop-carried value pinned to a register.
///
/// Register map: rax = pre-shifted container, ecx = bits consumed, rdx =
/// source cursor, rsi = tables, rdi = output slot, r8/r9/r10 = LL/ML/OF
/// states, r11/r12/r13 = rep offsets, r14/r15 = scratch; the loop bounds
/// (slot end, cursor low bound) live on the stack.
///
/// # Safety
/// As for [`decode_sequence_batch_rust`], plus BMI2 must be available.
#[cfg(target_arch = "x86_64")]
#[inline(never)]
unsafe fn decode_sequence_batch_bmi2(st: &mut FseState, tabs: *const SeqEntry, out: &mut SeqBatch, n: usize) -> usize {
    let (index, consumed0, container0, src) = st.bits.raw_parts();
    let mut consumed: u32 = consumed0;
    let mut acc: u64 = container0 << consumed;
    let mut cursor: *const u8 = unsafe { src.add(index) };
    let lo: *const u8 = unsafe { src.add(8) };
    let mut ll_state = st.ll_state;
    let mut ml_state = st.ml_state;
    let mut of_state = st.of_state;
    let [mut r0, mut r1, mut r2] = st.rep;
    let limit = n.min(st.left - 1);
    let out_start = out.as_mut_ptr();
    let mut slot = out_start;
    let end = unsafe { out_start.add(limit) };

    // read!(n in r14d) -> value in r15d; consumes n bits.
    macro_rules! read { () => { concat!(
        "mov r15, rax\n",
        "shr r15, 1\n",
        "add ecx, r14d\n",
        "shlx rax, rax, r14\n",
        "xor r14d, 63\n",
        "shrx r15, r15, r14\n",
    ) } }

    unsafe {
        core::arch::asm!(
            "push r14",                 // [rsp+8] = slot end
            "push r15",                 // [rsp]   = cursor low bound
            "2:",
            "cmp rdi, qword ptr [rsp+8]",
            "jae 9f",
            "cmp rdx, qword ptr [rsp]",
            "jb 9f",
            // total extra bits <= 31, else bail.
            "movzx r14d, byte ptr [rsi + r10*8 + 0x1002]",
            "movzx r15d, byte ptr [rsi + r9*8 + 0x2002]",
            "add r15d, r14d",
            "add r15b, byte ptr [rsi + r8*8 + 2]",
            "cmp r15d, 31",
            "ja 9f",
            // ---- offset ----
            "cmp r14d, 1",
            "jbe 3f",
            read!(),
            "add r15d, dword ptr [rsi + r10*8 + 0x1004]",
            "mov r13d, r12d",
            "mov r12d, r11d",
            "mov r11d, r15d",
            "jmp 5f",
            "3:",
            "test r14d, r14d",
            "jnz 4f",
            // of code 0: rep0, or swap(rep0, rep1) when lit_len == 0 —
            // branchless (cmov), the swap is unpredictable on text.
            "mov r15d, r11d",
            "mov r14d, r12d",
            "cmp dword ptr [rsi + r8*8 + 4], 0",
            "cmove r15d, r12d",
            "cmove r14d, r11d",
            "mov r12d, r14d",
            "mov r11d, r15d",
            "jmp 5f",
            "4:",
            // of code 1: idx = ll0 + 1 + bit
            "mov r15, rax",
            "shr r15, 63",
            "add rax, rax",
            "inc ecx",
            "xor r14d, r14d",
            "cmp dword ptr [rsi + r8*8 + 4], 0",
            "sete r14b",
            "add r15d, r14d",
            "jnz 6f",
            "mov r15d, r12d",
            "mov r12d, r11d",
            "mov r11d, r15d",
            "jmp 5f",
            "6:",
            "lea r14d, [r11 - 1]",
            "cmp r15d, 1",
            "mov r15d, r13d",
            "cmovne r15d, r14d",
            "mov r13d, r12d",
            "mov r12d, r11d",
            "mov r11d, r15d",
            "5:",
            "mov dword ptr [rdi + 8], r15d",
            // ---- match length ----
            "movzx r14d, byte ptr [rsi + r9*8 + 0x2002]",
            read!(),
            "add r15d, dword ptr [rsi + r9*8 + 0x2004]",
            "mov dword ptr [rdi + 4], r15d",
            // ---- literal length ----
            "movzx r14d, byte ptr [rsi + r8*8 + 2]",
            read!(),
            "add r15d, dword ptr [rsi + r8*8 + 4]",
            "mov dword ptr [rdi], r15d",
            // ---- state advance: LL, ML, OF ----
            "movzx r14d, byte ptr [rsi + r8*8 + 3]",
            read!(),
            "movzx r8d, word ptr [rsi + r8*8]",
            "add r8d, r15d",
            "movzx r14d, byte ptr [rsi + r9*8 + 0x2003]",
            read!(),
            "movzx r9d, word ptr [rsi + r9*8 + 0x2000]",
            "add r9d, r15d",
            "movzx r14d, byte ptr [rsi + r10*8 + 0x1003]",
            read!(),
            "movzx r10d, word ptr [rsi + r10*8 + 0x1000]",
            "add r10d, r15d",
            // ---- refill ----
            "mov r14d, ecx",
            "shr r14d, 3",
            "sub rdx, r14",
            "and ecx, 7",
            "shlx rax, qword ptr [rdx], rcx",
            "add rdi, 12",
            "jmp 2b",
            "9:",
            "add rsp, 16",
            inout("rax") acc,
            inout("ecx") consumed,
            inout("rdx") cursor,
            in("rsi") tabs,
            inout("rdi") slot,
            inout("r8d") ll_state,
            inout("r9d") ml_state,
            inout("r10d") of_state,
            inout("r11d") r0,
            inout("r12d") r1,
            inout("r13d") r2,
            inout("r14") end => _,
            inout("r15") lo => _,
        );
    }
    let done = unsafe { slot.offset_from(out_start) } as usize;
    let index = unsafe { cursor.offset_from(src) } as usize;
    st.bits.set_raw_parts(index, consumed, acc >> consumed);
    st.ll_state = ll_state;
    st.of_state = of_state;
    st.ml_state = ml_state;
    st.rep = [r0, r1, r2];
    st.left -= done;
    done
}

/// Dispatch: BMI2 asm on x86_64 when available, portable Rust otherwise.
#[inline(always)]
unsafe fn decode_sequence_batch(st: &mut FseState, tabs: *const SeqEntry, out: &mut SeqBatch, n: usize) -> usize {
    #[cfg(target_arch = "x86_64")]
    {
        if crate::cpu_features::has_bmi2() {
            return unsafe { decode_sequence_batch_bmi2(st, tabs, out, n) };
        }
    }
    unsafe { decode_sequence_batch_rust(st, tabs, out, n) }
}

/// Byte tables for the `offset < 8` overlapping match copy (lz4's
/// `inc32table` / `dec64table`), referenced from the asm loop.
#[cfg(target_arch = "x86_64")]
static OVL_INC32: [u8; 8] = [0, 1, 2, 1, 0, 4, 4, 4];
#[cfg(target_arch = "x86_64")]
static OVL_DEC64: [i8; 8] = [0, 0, 0, -1, -4, 1, 2, 3];

/// In/out block for [`decode_exec_bmi2`] (everything that doesn't fit in
/// the 13 nameable registers).
#[cfg(target_arch = "x86_64")]
#[repr(C)]
struct ExecArgs {
    cursor_lo: *const u8,
    lit_end: *const u8,
    out_base: *mut u8,
    left: usize,
    dst: *mut u8,
    lit: *const u8,
    status: usize,
}

/// Fused x86_64 BMI2 sequence loop: decode one sequence, advance the FSE
/// states, refill, execute the literal + match copies — all in registers,
/// like `ZSTD_decompressSequences_bmi2`. The split decode/execute batches
/// were instruction-count parity with C but ~20% slower on small inputs
/// and L1 streams: phase A is a pure FSE latency chain with nothing to
/// overlap, whereas a fused loop lets the OOO core hide it behind the
/// copies of the previous sequence.
///
/// Stops (returning normally) before any sequence it can't handle — the
/// last one (no state advance), fewer than 8 source bytes ahead (slow
/// refill), or > 31 extra bits; the caller runs that one sequence through
/// the general path and re-enters. Sets `status = 1` and stops on a
/// literal / offset validation failure (nothing was written for that
/// sequence; the bit state is then garbage but the caller reports an error).
///
/// Register map: rax = pre-shifted container, ecx = bits consumed, rdx =
/// source cursor, rsi = tables, rdi = output write cursor, rbx = literal
/// read cursor, r8/r9/r10 = LL/ML/OF states, r11/r12/r13 = rep offsets,
/// r14/r15/rbp = scratch. Stack slots (below the saved rbx/rbp): cursor low
/// bound, lit end, out base, count left, offset/ml/ll spills, cursor spill,
/// args pointer.
///
/// # Safety
/// Same requirements as `decode_sequences` (tables, literal padding of 32
/// bytes, `ZSTD_BLOCKSIZE_MAX + 32` bytes of output headroom); BMI2.
#[cfg(target_arch = "x86_64")]
#[inline(never)]
unsafe fn decode_exec_bmi2(st: &mut FseState, tabs: *const SeqEntry, args: &mut ExecArgs) {
    let (index, consumed0, container0, src) = st.bits.raw_parts();
    let mut consumed: u32 = consumed0;
    let mut acc: u64 = container0 << consumed;
    let mut cursor: *const u8 = unsafe { src.add(index) };
    args.cursor_lo = unsafe { src.add(8) };
    args.left = st.left;
    args.status = 0;
    let mut ll_state = st.ll_state;
    let mut ml_state = st.ml_state;
    let mut of_state = st.of_state;
    let [mut r0, mut r1, mut r2] = st.rep;

    // read!(): n in r14d -> value in r15d; consumes n bits (clobbers r14).
    macro_rules! read { () => { concat!(
        "mov r15, rax\n",
        "shr r15, 1\n",
        "add ecx, r14d\n",
        "shlx rax, rax, r14\n",
        "xor r14d, 63\n",
        "shrx r15, r15, r14\n",
    ) } }

    unsafe {
        core::arch::asm!(
            "push rbx",
            "push rbp",
            "sub rsp, 64",
            // slots: [0]=cursor_lo [8]=lit_end [16]=out_base [24]=left
            //        [32]=off [40]=ml [48]=ll/cursor spill [56]=args
            "mov [rsp+56], rdi",
            "mov r14, [rdi]",       "mov [rsp], r14",
            "mov r14, [rdi+8]",     "mov [rsp+8], r14",
            "mov r14, [rdi+16]",    "mov [rsp+16], r14",
            "mov r14, [rdi+24]",    "mov [rsp+24], r14",
            "mov rbx, [rdi+40]",
            "mov rdi, [rdi+32]",
            "2:",
            "cmp qword ptr [rsp+24], 1",
            "jbe 9f",
            "cmp rdx, qword ptr [rsp]",
            "jb 9f",
            // total extra bits <= 31, else bail.
            "movzx r14d, byte ptr [rsi + r10*8 + 0x1002]",
            "movzx r15d, byte ptr [rsi + r9*8 + 0x2002]",
            "add r15d, r14d",
            "add r15b, byte ptr [rsi + r8*8 + 2]",
            "cmp r15d, 31",
            "ja 9f",
            // ---- offset ----
            "cmp r14d, 1",
            "jbe 3f",
            read!(),
            "add r15d, dword ptr [rsi + r10*8 + 0x1004]",
            "mov r13d, r12d",
            "mov r12d, r11d",
            "mov r11d, r15d",
            "jmp 5f",
            "3:",
            "test r14d, r14d",
            "jnz 4f",
            "mov r15d, r11d",
            "mov r14d, r12d",
            "cmp dword ptr [rsi + r8*8 + 4], 0",
            "cmove r15d, r12d",
            "cmove r14d, r11d",
            "mov r12d, r14d",
            "mov r11d, r15d",
            "jmp 5f",
            "4:",
            "mov r15, rax",
            "shr r15, 63",
            "add rax, rax",
            "inc ecx",
            "xor r14d, r14d",
            "cmp dword ptr [rsi + r8*8 + 4], 0",
            "sete r14b",
            "add r15d, r14d",
            "jnz 6f",
            "mov r15d, r12d",
            "mov r12d, r11d",
            "mov r11d, r15d",
            "jmp 5f",
            "6:",
            "lea r14d, [r11 - 1]",
            "cmp r15d, 1",
            "mov r15d, r13d",
            "cmovne r15d, r14d",
            "mov r13d, r12d",
            "mov r12d, r11d",
            "mov r11d, r15d",
            "5:",
            "mov [rsp+32], r15",
            // ---- match length ----
            "movzx r14d, byte ptr [rsi + r9*8 + 0x2002]",
            read!(),
            "add r15d, dword ptr [rsi + r9*8 + 0x2004]",
            "mov [rsp+40], r15",
            // ---- literal length ----
            "movzx r14d, byte ptr [rsi + r8*8 + 2]",
            read!(),
            "add r15d, dword ptr [rsi + r8*8 + 4]",
            "mov [rsp+48], r15",
            // ---- state advance: LL, ML, OF ----
            "movzx r14d, byte ptr [rsi + r8*8 + 3]",
            read!(),
            "movzx r8d, word ptr [rsi + r8*8]",
            "add r8d, r15d",
            "movzx r14d, byte ptr [rsi + r9*8 + 0x2003]",
            read!(),
            "movzx r9d, word ptr [rsi + r9*8 + 0x2000]",
            "add r9d, r15d",
            "movzx r14d, byte ptr [rsi + r10*8 + 0x1003]",
            read!(),
            "movzx r10d, word ptr [rsi + r10*8 + 0x1000]",
            "add r10d, r15d",
            // ---- refill ----
            "mov r14d, ecx",
            "shr r14d, 3",
            "sub rdx, r14",
            "and ecx, 7",
            "shlx rax, qword ptr [rdx], rcx",
            // ---- execute: validate ----
            "mov r15, [rsp+48]",            // ll
            "lea r14, [rbx + r15]",
            "cmp r14, qword ptr [rsp+8]",   // lit + ll > lit_end -> error
            "ja 8f",
            "lea r14, [rdi + r15]",
            "sub r14, qword ptr [rsp+16]",  // post_lit - out_base
            "mov rbp, [rsp+32]",
            "dec rbp",                      // off - 1 (off == 0 wraps)
            "cmp rbp, r14",
            "jae 8f",
            // ---- literal copy (16-byte steps; literals padded by 32) ----
            "mov r14, rdi",
            "mov rbp, rbx",
            "add rdi, r15",
            "add rbx, r15",
            "movdqu xmm0, [rbp]",
            "movdqu [r14], xmm0",
            "cmp r15, 16",
            "jbe 20f",
            "21:",
            "add rbp, 16",
            "add r14, 16",
            "movdqu xmm0, [rbp]",
            "movdqu [r14], xmm0",
            "cmp r14, rdi",
            "jb 21b",
            "20:",
            // ---- match copy ----
            "mov r14, [rsp+32]",            // off
            "mov r15, [rsp+40]",            // ml
            "mov rbp, rdi",
            "sub rbp, r14",                 // src
            "add r15, rdi",                 // end
            "cmp r14, 16",
            "jb 30f",
            "movdqu xmm0, [rbp]",
            "movdqu [rdi], xmm0",
            "add rdi, 16",
            "cmp rdi, r15",
            "jae 39f",
            "add rbp, 16",
            "31:",
            "movdqu xmm0, [rbp]",
            "movdqu [rdi], xmm0",
            "movdqu xmm1, [rbp + 16]",
            "movdqu [rdi + 16], xmm1",
            "add rbp, 32",
            "add rdi, 32",
            "cmp rdi, r15",
            "jb 31b",
            "jmp 39f",
            "30:",
            // offset < 16: first 8 bytes with the inc32/dec64 fix-up, then
            // 8-byte steps. rdx (cursor) is spilled to free a byte register.
            "mov [rsp+48], rdx",
            "cmp r14, 8",
            "jae 32f",
            "movzx edx, byte ptr [rbp]",     "mov [rdi], dl",
            "movzx edx, byte ptr [rbp + 1]", "mov [rdi + 1], dl",
            "movzx edx, byte ptr [rbp + 2]", "mov [rdi + 2], dl",
            "movzx edx, byte ptr [rbp + 3]", "mov [rdi + 3], dl",
            "lea rdx, [rip + {inc32}]",
            "movzx edx, byte ptr [rdx + r14]",
            "add rbp, rdx",
            "mov edx, dword ptr [rbp]",
            "mov [rdi + 4], edx",
            "lea rdx, [rip + {dec64}]",
            "movsx rdx, byte ptr [rdx + r14]",
            "sub rbp, rdx",
            "jmp 33f",
            "32:",
            "mov rdx, [rbp]",
            "mov [rdi], rdx",
            "add rbp, 8",
            "33:",
            "add rdi, 8",
            "cmp rdi, r15",
            "jae 34f",
            "35:",
            "mov rdx, [rbp]",
            "mov [rdi], rdx",
            "add rbp, 8",
            "add rdi, 8",
            "cmp rdi, r15",
            "jb 35b",
            "34:",
            "mov rdx, [rsp+48]",
            "39:",
            "mov rdi, r15",
            "dec qword ptr [rsp+24]",
            "jmp 2b",
            "8:",
            "mov r14, [rsp+56]",
            "mov qword ptr [r14+48], 1",
            "9:",
            "mov r14, [rsp+56]",
            "mov [r14+32], rdi",
            "mov [r14+40], rbx",
            "mov r15, [rsp+24]",
            "mov [r14+24], r15",
            "add rsp, 64",
            "pop rbp",
            "pop rbx",
            inc32 = sym OVL_INC32,
            dec64 = sym OVL_DEC64,
            inout("rax") acc,
            inout("ecx") consumed,
            inout("rdx") cursor,
            in("rsi") tabs,
            inout("rdi") args as *mut ExecArgs => _,
            inout("r8d") ll_state,
            inout("r9d") ml_state,
            inout("r10d") of_state,
            inout("r11d") r0,
            inout("r12d") r1,
            inout("r13d") r2,
            out("r14") _,
            out("r15") _,
            out("xmm0") _,
            out("xmm1") _,
        );
    }
    let index = unsafe { cursor.offset_from(src) } as usize;
    st.bits.set_raw_parts(index, consumed, acc >> consumed);
    st.ll_state = ll_state;
    st.of_state = of_state;
    st.ml_state = ml_state;
    st.rep = [r0, r1, r2];
    st.left = args.left;
}

/// The sequence section: decode in batches (fast path + general fallback)
/// and execute each batch's literal + match copies with only the output /
/// literal cursors live.
///
/// Returns `(dst_off, lit_pos)`.
///
/// # Safety
/// * `tabs` must point at `3 * SEQ_TAB_STRIDE` entries holding the LL, OF,
///   ML tables at strides 0, 1, 2 with the given accuracy logs.
/// * `lit_ptr` must point to at least `lit_total + 32` readable bytes.
/// * `out_base + out_off` must have `ZSTD_BLOCKSIZE_MAX + 32` bytes of
///   writable headroom.
#[inline(never)]
#[allow(clippy::too_many_arguments)]
unsafe fn decode_sequences(
    bitstream: &[u8],
    tabs: *const SeqEntry,
    acc_log: [u32; 3],
    num_sequences: usize,
    lit_ptr: *const u8,
    lit_total: usize,
    out_base: *mut u8,
    out_off: usize,
    rep_io: &mut [u32; 3],
) -> io::Result<(usize, usize)> {
    let mut bits = ReverseBitReader::new(bitstream)?;
    bits.skip_padding_bits()?;
    // Initial states (order per RFC 8878 3.1.2.1.2.4), then establish the
    // invariant: >= 57 bits in the container (or stream start reached) at
    // the top of every sequence.
    let ll_state = bits.get_bits(acc_log[0]);
    let of_state = bits.get_bits(acc_log[1]);
    let ml_state = bits.get_bits(acc_log[2]);
    bits.refill();
    let mut st = FseState { bits, ll_state, of_state, ml_state, rep: *rep_io, left: num_sequences };

    let mut lit_pos = 0usize;
    let mut dst = out_off;
    let mut seqs: SeqBatch = [Seq::default(); SEQ_BATCH];
    #[cfg(target_arch = "x86_64")]
    let fused = crate::cpu_features::has_bmi2();
    #[cfg(not(target_arch = "x86_64"))]
    let fused = false;

    while st.left != 0 {
        let mut n;
        #[cfg(target_arch = "x86_64")]
        if fused {
            let mut args = ExecArgs {
                cursor_lo: core::ptr::null(),
                lit_end: unsafe { lit_ptr.add(lit_total) },
                out_base,
                left: 0,
                dst: unsafe { out_base.add(dst) },
                lit: unsafe { lit_ptr.add(lit_pos) },
                status: 0,
            };
            unsafe { decode_exec_bmi2(&mut st, tabs, &mut args) };
            dst = unsafe { args.dst.offset_from(out_base) } as usize;
            lit_pos = unsafe { args.lit.offset_from(lit_ptr) } as usize;
            if args.status != 0 {
                return Err(seq_validation_error(lit_pos, 0, lit_total, 0, dst));
            }
            if st.left == 0 {
                break;
            }
            // One sequence the fast loop declined (last / stream start /
            // long extras): general decode, executed by the loop below.
            seqs[0] = unsafe { decode_sequence_general(&mut st, tabs) };
            n = 1;
        } else {
            n = unsafe { decode_sequence_batch(&mut st, tabs, &mut seqs, SEQ_BATCH) };
            if n < SEQ_BATCH && st.left != 0 {
                seqs[n] = unsafe { decode_sequence_general(&mut st, tabs) };
                n += 1;
            }
        }
        #[cfg(not(target_arch = "x86_64"))]
        {
            n = unsafe { decode_sequence_batch(&mut st, tabs, &mut seqs, SEQ_BATCH) };
            if n < SEQ_BATCH && st.left != 0 {
                seqs[n] = unsafe { decode_sequence_general(&mut st, tabs) };
                n += 1;
            }
        }

        for &Seq { lit_len, match_len, offset } in seqs.iter().take(n) {
            let lit_len = lit_len as usize;
            let post_lit = dst + lit_len;
            let off = offset as usize;
            let bad_lit = (lit_pos + lit_len > lit_total) as u32;
            let bad_off = (off.wrapping_sub(1) >= post_lit) as u32; // off == 0 || off > post_lit
            if (bad_lit | bad_off) != 0 {
                return Err(seq_validation_error(lit_pos, lit_len, lit_total, offset, post_lit));
            }
            unsafe {
                crate::cpu_features::wildcopy_chunks::<16>(lit_ptr.add(lit_pos), out_base.add(dst), lit_len);
                crate::cpu_features::copy_match_unchecked_32(
                    out_base.add(post_lit - off),
                    out_base.add(post_lit),
                    off,
                    match_len as usize,
                );
            }
            lit_pos += lit_len;
            dst = post_lit + match_len as usize;
        }
    }
    *rep_io = st.rep;
    Ok((dst, lit_pos))
}

// ---------------------------------------------------------------------------
// Literals section
// ---------------------------------------------------------------------------

/// Decode the literals section. Returns `(ptr, len)` of the literals; the
/// pointer is followed by at least 16 readable bytes so the sequence loop's
/// 16-byte wildcopy may over-read. Raw literals are referenced in place in
/// the block (`block`) when enough input follows them — like C zstd, no
/// copy; otherwise (and for RLE / Huffman literals) they go into `buf`.
#[inline(never)]
fn decode_literals_section_into(
    r: &mut ForwardByteReader,
    block: &[u8],
    huf_table: &mut Option<HufTable>,
    buf: &mut Vec<u8>,
) -> io::Result<(*const u8, usize)> {
    let byte0 = r.read_u8()?;
    let lit_type = byte0 & 3;
    let size_format = (byte0 >> 2) & 3;

    match lit_type {
        0 => {
            // Raw literals.
            let regen_size = decode_lit_size_raw(byte0, size_format, r)?;
            let raw = r.read_bytes(regen_size)?;
            if r.position() + 16 <= block.len() {
                return Ok((raw.as_ptr(), regen_size));
            }
            buf.clear();
            buf.extend_from_slice(raw);
            buf.resize(regen_size + 32, 0);
            Ok((buf.as_ptr(), regen_size))
        }
        1 => {
            // RLE literals.
            let regen_size = decode_lit_size_raw(byte0, size_format, r)?;
            let byte = r.read_u8()?;
            buf.clear();
            buf.resize(regen_size + 32, byte);
            Ok((buf.as_ptr(), regen_size))
        }
        2 | 3 => {
            // Compressed or Treeless literals.
            let (regen_size, compressed_size, four_streams) =
                decode_lit_size_compressed(byte0, size_format, r)?;

            let lit_data = r.read_bytes(compressed_size)?;
            let mut pos = 0;

            if lit_type == 2 {
                // New Huffman tree.
                let (table, consumed) = HufTable::decode_from_stream(lit_data)?;
                *huf_table = Some(table);
                pos = consumed;
            }
            // Treeless (3) reuses the previous Huffman table.

            let table = huf_table
                .as_ref()
                .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "zstd: treeless literals without prior Huffman table"))?;

            let stream_data = &lit_data[pos..];
            // The decoders write every one of the `regen_size` bytes, so
            // skip the zero-fill: reserve + set_len, then append the
            // 16+ byte dead zone the sequence loop over-reads.
            buf.clear();
            buf.reserve(regen_size + 32);
            // SAFETY: capacity reserved; every byte is written by the
            // decoder below before it is read (on error the buffer is
            // never read).
            unsafe { buf.set_len(regen_size) };
            if four_streams {
                super::huf::decode_literals_4stream_into(table, stream_data, buf)?;
            } else {
                super::huf::decode_literals_1stream_into(table, stream_data, buf)?;
            }
            buf.resize(regen_size + 32, 0);
            Ok((buf.as_ptr(), regen_size))
        }
        _ => unreachable!(),
    }
}

fn decode_lit_size_raw(byte0: u8, size_format: u8, r: &mut ForwardByteReader) -> io::Result<usize> {
    // Per RFC 8878 §3.1.1.3.1.1 — size_format encoding for Raw/RLE literals:
    //   00 or 10 → 1-byte header, 5-bit regen size
    //   01       → 2-byte header, 12-bit regen size
    //   11       → 3-byte header, 20-bit regen size
    match size_format {
        0 | 2 => Ok((byte0 >> 3) as usize),
        1 => {
            let b1 = r.read_u8()?;
            Ok(((byte0 as usize >> 4) | ((b1 as usize) << 4)) & 0xFFF)
        }
        3 => {
            let b1 = r.read_u8()?;
            let b2 = r.read_u8()?;
            Ok(((byte0 as usize >> 4) | ((b1 as usize) << 4) | ((b2 as usize) << 12)) & 0xFFFFF)
        }
        _ => unreachable!(),
    }
}

fn decode_lit_size_compressed(
    byte0: u8,
    size_format: u8,
    r: &mut ForwardByteReader,
) -> io::Result<(usize, usize, bool)> {
    match size_format {
        0 => {
            // Single stream: 10-bit regen, 10-bit compressed.
            let b1 = r.read_u8()?;
            let b2 = r.read_u8()?;
            let combined = (byte0 as u32 >> 4) | ((b1 as u32) << 4) | ((b2 as u32) << 12);
            let regen = (combined & 0x3FF) as usize;
            let compressed = ((combined >> 10) & 0x3FF) as usize;
            Ok((regen, compressed, false))
        }
        1 => {
            let b1 = r.read_u8()?;
            let b2 = r.read_u8()?;
            let combined = (byte0 as u32 >> 4) | ((b1 as u32) << 4) | ((b2 as u32) << 12);
            let regen = (combined & 0x3FF) as usize;
            let compressed = ((combined >> 10) & 0x3FF) as usize;
            Ok((regen, compressed, true))
        }
        2 => {
            let b1 = r.read_u8()?;
            let b2 = r.read_u8()?;
            let b3 = r.read_u8()?;
            let combined = (byte0 as u32 >> 4) | ((b1 as u32) << 4) | ((b2 as u32) << 12) | ((b3 as u32) << 20);
            let regen = (combined & 0x3FFF) as usize;
            let compressed = ((combined >> 14) & 0x3FFF) as usize;
            Ok((regen, compressed, true))
        }
        3 => {
            let b1 = r.read_u8()?;
            let b2 = r.read_u8()?;
            let b3 = r.read_u8()?;
            let b4 = r.read_u8()?;
            // 18-bit regen + 18-bit compressed = 36 bits total — must be a
            // u64 because a u32 silently drops the top 4 bits of `b4`,
            // which corrupts compressed_size for any block where it's
            // ≥ 16384 (i.e. essentially every text-heavy L1 block).
            let combined = (byte0 as u64 >> 4)
                | ((b1 as u64) << 4)
                | ((b2 as u64) << 12)
                | ((b3 as u64) << 20)
                | ((b4 as u64) << 28);
            let regen = (combined & 0x3FFFF) as usize;
            let compressed = ((combined >> 18) & 0x3FFFF) as usize;
            Ok((regen, compressed, true))
        }
        _ => unreachable!(),
    }
}

// ---------------------------------------------------------------------------
// Sequences section
// ---------------------------------------------------------------------------

fn decode_sequence_count(r: &mut ForwardByteReader) -> io::Result<usize> {
    let byte0 = r.read_u8()? as usize;
    if byte0 < 128 {
        Ok(byte0)
    } else if byte0 < 255 {
        let byte1 = r.read_u8()? as usize;
        Ok(((byte0 - 128) << 8) + byte1)
    } else {
        let lo = r.read_u8()? as usize;
        let hi = r.read_u8()? as usize;
        Ok(lo + (hi << 8) + 0x7F00)
    }
}

fn decode_seq_table_mode(
    r: &mut ForwardByteReader,
    mode: u8,
    table: &mut Option<SeqTable>,
    max_symbol: u32,
    max_accuracy_log: u32,
    kind: SeqKind,
) -> io::Result<()> {
    // Per RFC 8878 §3.1.1.3.2.1.1 — Symbol_Compression_Mode:
    //   00 → Predefined, 01 → RLE, 10 → FSE_Compressed, 11 → Repeat
    match mode {
        0 => *table = Some(SeqTable::predefined(kind)),
        1 => {
            let sym = r.read_u8()?;
            if sym as u32 > max_symbol {
                return Err(io::Error::new(io::ErrorKind::InvalidData, "zstd: RLE symbol out of range"));
            }
            *table = Some(SeqTable::rle(sym, kind));
        }
        2 => {
            let fse = FseTable::decode_table(r, max_symbol, max_accuracy_log)?;
            *table = Some(SeqTable::from_fse(&fse, kind));
        }
        3 => {
            if table.is_none() {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "zstd: repeat mode without prior FSE table",
                ));
            }
        }
        _ => unreachable!(),
    }
    Ok(())
}

// ---------------------------------------------------------------------------
// Sequence value decoding
// ---------------------------------------------------------------------------

/// Cold error helper for the sequence-loop safety checks. Out-of-line so the
/// hot path only pays for one taken branch + one fall-through, not the
/// register spilling that `format!` would force inline.
#[cold]
#[inline(never)]
fn seq_validation_error(
    lit_pos: usize,
    lit_len: usize,
    lit_total: usize,
    offset: u32,
    post_lit: usize,
) -> io::Error {
    if lit_pos + lit_len > lit_total {
        return io::Error::new(
            io::ErrorKind::InvalidData,
            "zstd: literals length exceeds available literals",
        );
    }
    io::Error::new(
        io::ErrorKind::InvalidData,
        format!(
            "zstd: match offset {} exceeds available history {}",
            offset, post_lit
        ),
    )
}

// ---------------------------------------------------------------------------
// XXHash64 (lower 32 bits) for content checksum
// ---------------------------------------------------------------------------

/// Incremental XXH64 (seed 0) for the frame content checksum when the
/// output is flushed to the sink before the frame ends.
struct Xxh64 {
    v: [u64; 4],
    buf: [u8; 32],
    buf_len: usize,
    total: u64,
}

impl Xxh64 {
    const P1: u64 = 0x9E3779B185EBCA87;
    const P2: u64 = 0xC2B2AE3D27D4EB4F;
    const P3: u64 = 0x165667B19E3779F9;
    const P4: u64 = 0x85EBCA77C2B2AE63;
    const P5: u64 = 0x27D4EB2F165667C5;

    fn new() -> Self {
        Self {
            v: [Self::P1.wrapping_add(Self::P2), Self::P2, 0, 0u64.wrapping_sub(Self::P1)],
            buf: [0; 32],
            buf_len: 0,
            total: 0,
        }
    }

    fn stripe(&mut self, b: &[u8]) {
        for k in 0..4 {
            self.v[k] = xxh64_round(self.v[k], read_u64_le(b, k * 8));
        }
    }

    fn update(&mut self, mut data: &[u8]) {
        self.total += data.len() as u64;
        if self.buf_len > 0 {
            let take = (32 - self.buf_len).min(data.len());
            self.buf[self.buf_len..self.buf_len + take].copy_from_slice(&data[..take]);
            self.buf_len += take;
            data = &data[take..];
            if self.buf_len < 32 {
                return;
            }
            let b = self.buf;
            self.stripe(&b);
            self.buf_len = 0;
        }
        let mut i = 0;
        while i + 32 <= data.len() {
            self.stripe(&data[i..i + 32]);
            i += 32;
        }
        let rest = data.len() - i;
        self.buf[..rest].copy_from_slice(&data[i..]);
        self.buf_len = rest;
    }

    fn finish(&self) -> u64 {
        let mut h = if self.total >= 32 {
            let [v1, v2, v3, v4] = self.v;
            let mut h = v1.rotate_left(1)
                .wrapping_add(v2.rotate_left(7))
                .wrapping_add(v3.rotate_left(12))
                .wrapping_add(v4.rotate_left(18));
            h = xxh64_merge(h, v1);
            h = xxh64_merge(h, v2);
            h = xxh64_merge(h, v3);
            xxh64_merge(h, v4)
        } else {
            Self::P5
        };
        h = h.wrapping_add(self.total);
        let data = &self.buf[..self.buf_len];
        let mut i = 0;
        while i + 8 <= data.len() {
            h ^= xxh64_round(0, read_u64_le(data, i));
            h = h.rotate_left(27).wrapping_mul(Self::P1).wrapping_add(Self::P4);
            i += 8;
        }
        while i + 4 <= data.len() {
            let k = u32::from_le_bytes(data[i..i + 4].try_into().unwrap()) as u64;
            h ^= k.wrapping_mul(Self::P1);
            h = h.rotate_left(23).wrapping_mul(Self::P2).wrapping_add(Self::P3);
            i += 4;
        }
        while i < data.len() {
            h ^= (data[i] as u64).wrapping_mul(Self::P5);
            h = h.rotate_left(11).wrapping_mul(Self::P1);
            i += 1;
        }
        h ^= h >> 33;
        h = h.wrapping_mul(Self::P2);
        h ^= h >> 29;
        h = h.wrapping_mul(Self::P3);
        h ^= h >> 32;
        h
    }
}

/// XXHash64 — public for use by the encoder checksum.
pub fn xxhash64_public(data: &[u8], seed: u64) -> u64 {
    xxhash64(data, seed)
}

fn xxhash64(data: &[u8], seed: u64) -> u64 {
    const PRIME1: u64 = 0x9E3779B185EBCA87;
    const PRIME2: u64 = 0xC2B2AE3D27D4EB4F;
    const PRIME3: u64 = 0x165667B19E3779F9;
    const PRIME4: u64 = 0x85EBCA77C2B2AE63;
    const PRIME5: u64 = 0x27D4EB2F165667C5;

    let len = data.len();
    let mut h: u64;
    let mut i = 0;

    if len >= 32 {
        let mut v1 = seed.wrapping_add(PRIME1).wrapping_add(PRIME2);
        let mut v2 = seed.wrapping_add(PRIME2);
        let mut v3 = seed;
        let mut v4 = seed.wrapping_sub(PRIME1);

        while i + 32 <= len {
            v1 = xxh64_round(v1, read_u64_le(data, i));
            v2 = xxh64_round(v2, read_u64_le(data, i + 8));
            v3 = xxh64_round(v3, read_u64_le(data, i + 16));
            v4 = xxh64_round(v4, read_u64_le(data, i + 24));
            i += 32;
        }

        h = v1.rotate_left(1)
            .wrapping_add(v2.rotate_left(7))
            .wrapping_add(v3.rotate_left(12))
            .wrapping_add(v4.rotate_left(18));
        h = xxh64_merge(h, v1);
        h = xxh64_merge(h, v2);
        h = xxh64_merge(h, v3);
        h = xxh64_merge(h, v4);
    } else {
        h = seed.wrapping_add(PRIME5);
    }

    h = h.wrapping_add(len as u64);

    while i + 8 <= len {
        let k = read_u64_le(data, i);
        h ^= xxh64_round(0, k);
        h = h.rotate_left(27).wrapping_mul(PRIME1).wrapping_add(PRIME4);
        i += 8;
    }

    while i + 4 <= len {
        let k = u32::from_le_bytes(data[i..i + 4].try_into().unwrap()) as u64;
        h ^= k.wrapping_mul(PRIME1);
        h = h.rotate_left(23).wrapping_mul(PRIME2).wrapping_add(PRIME3);
        i += 4;
    }

    while i < len {
        h ^= (data[i] as u64).wrapping_mul(PRIME5);
        h = h.rotate_left(11).wrapping_mul(PRIME1);
        i += 1;
    }

    // Finalize.
    h ^= h >> 33;
    h = h.wrapping_mul(PRIME2);
    h ^= h >> 29;
    h = h.wrapping_mul(PRIME3);
    h ^= h >> 32;
    h
}

#[inline(always)]
fn xxh64_round(mut acc: u64, input: u64) -> u64 {
    const PRIME1: u64 = 0x9E3779B185EBCA87;
    const PRIME2: u64 = 0xC2B2AE3D27D4EB4F;
    acc = acc.wrapping_add(input.wrapping_mul(PRIME2));
    acc = acc.rotate_left(31);
    acc.wrapping_mul(PRIME1)
}

#[inline(always)]
fn xxh64_merge(mut h: u64, v: u64) -> u64 {
    const PRIME1: u64 = 0x9E3779B185EBCA87;
    const PRIME4: u64 = 0x85EBCA77C2B2AE63;
    h ^= xxh64_round(0, v);
    h.wrapping_mul(PRIME1).wrapping_add(PRIME4)
}

#[inline(always)]
fn read_u64_le(data: &[u8], pos: usize) -> u64 {
    u64::from_le_bytes(data[pos..pos + 8].try_into().unwrap())
}
